// 历史只核原真实来源截面；今日换控、成年或死亡不会重写已发生的私人会话。
#include "known_personal_dialogue_detail.hpp"
#include <set>
namespace hanmo::resident {
Outcome<bool> match_known_personal_dialogue_session(const CommonStore& common,const KnownPersonalDialogueState& state,const KnownPersonalDialogueCatalog& catalog,const InteractionCatalog& definitions,const InteractionSession& session){
 const auto* o=known_personal_detail::opening(state,session.id);if(!o)return {true,false,{}};auto fail=[&]()->Outcome<bool>{return {false,{},common_failure("KnownPersonalDialogueSessionMismatch",session.id).error};};const auto* t=known_personal_dialogue_template(catalog,o->template_id);const auto* d=known_personal_detail::dialogue(definitions,o->dialogue_id);const auto* head=common.state().facts.find(o->fact_id);const auto sid=known_personal_detail::serial(common,o->session_id,"interaction"),fid=known_personal_detail::serial(common,o->fact_id,known_personal_dialogue_opened_kind);
 if(state.version!=1||!t||!d||!d->context_role.empty()||t->dialogue_id!=o->dialogue_id||!known_personal_detail::matches(t->listener,o->listener_origin)||!known_personal_detail::matches(t->provider,o->provider_origin)||!head||head->id!=o->fact_id||head->domain!=known_personal_dialogue_module||head->kind!=known_personal_dialogue_opened_kind||!sid||!fid||*sid+1!=*fid||session.actor_id!=o->listener_origin.actor_id||session.dialogue_id!=o->dialogue_id||session.context.provider_actor_id!=o->provider_origin.actor_id||session.context.place_id!=o->place_id||!known_personal_detail::narrative(session.context)||session.regional_binding||session.regional_action_committed||session.pending_command||!session.pending_action_id.empty()||session.trade_completed||session.last_outcome.present)return fail();const auto* node=known_personal_detail::node(*d,session.node_id);if(!node)return fail();if(session.phase=="stepping"){if(node->kind!="say"&&node->kind!="choice"&&node->kind!="end")return fail();}else if((session.phase!="say"&&session.phase!="choice")||node->kind!=session.phase)return fail();return {true,true,{}};
}
Status validate_known_personal_dialogues(const KnownPersonalDialogueContext& x){
 auto valid=validate_known_personal_dialogue_catalog(x.catalog,x.definitions,x.family_catalog,x.birth_catalog);if(!valid.ok)return valid;if(x.state.version!=1||x.state.openings.size()>65536)return common_failure("InvalidKnownPersonalDialogueState");if(!x.sources.presence_before||!x.sources.player_before)return common_failure("KnownPersonalDialogueHistoryRequired");
 std::set<StableId> sessions;std::vector<StableId> headers;Integer last=0,last_tick=0;for(const auto& row:x.common.state().facts.rows())if(row.second.domain==known_personal_dialogue_module||row.second.kind==known_personal_dialogue_opened_kind){if(row.second.id!=row.first||row.second.domain!=known_personal_dialogue_module||row.second.kind!=known_personal_dialogue_opened_kind||!x.state.openings.find(row.first))return common_failure("InvalidKnownPersonalDialogueHeader",row.first);headers.push_back(row.first);}if(headers!=x.state.openings.order())return common_failure("KnownPersonalDialogueFactOrderMismatch");
 for(const auto& row:x.state.openings.rows()){const auto& o=row.second;const auto id=known_personal_detail::serial(x.common,row.first,known_personal_dialogue_opened_kind),sid=known_personal_detail::serial(x.common,o.session_id,"interaction");const auto* t=known_personal_dialogue_template(x.catalog,o.template_id);if(o.fact_id!=row.first||!id||!sid||*sid+1!=*id||*sid<=last||!sessions.insert(o.session_id).second||!t||t->dialogue_id!=o.dialogue_id||o.listener_origin.actor_id==o.provider_origin.actor_id||!x.definitions.common->places.find(o.place_id)||o.tick<last_tick||o.tick>x.common.tick())return common_failure("InvalidKnownPersonalDialogueOpening",row.first);last=*id;last_tick=o.tick;
  auto a=read_known_personal_actor_origin_before_fact(x.common,*x.definitions.common,x.sources,t->listener,o.listener_origin.actor_id,o.tick,o.fact_id);if(!a.ok)return {false,{},a.error};auto b=read_known_personal_actor_origin_before_fact(x.common,*x.definitions.common,x.sources,t->provider,o.provider_origin.actor_id,o.tick,o.fact_id);if(!b.ok)return {false,{},b.error};if(!same_known_personal_actor_origin(a.value,o.listener_origin)||!same_known_personal_actor_origin(b.value,o.provider_origin))return common_failure("KnownPersonalDialogueOriginMismatch",o.fact_id);auto player=x.sources.player_before(o.tick,o.fact_id);if(!player.ok)return {false,{},player.error};if(player.value!=o.listener_origin.actor_id)return common_failure("KnownPersonalDialogueHistoricalPlayerRequired",o.fact_id);
 }
 std::set<StableId> current;for(const auto& s:x.interactions.interactions){auto match=match_known_personal_dialogue_session(x.common,x.state,x.catalog,x.definitions,s);if(!match.ok)return {false,{},match.error};if(!match.value)continue;for(const auto& other:x.interactions.interactions)if(&other!=&s&&(known_personal_detail::involved(other,s.actor_id)||known_personal_detail::involved(other,s.context.provider_actor_id)))return common_failure("KnownPersonalDialogueDoubleOccupation",s.id);if(s.phase!="say"&&s.phase!="choice")return common_failure("InvalidKnownPersonalDialogueContinuePoint",s.id);if(!current.insert(s.id).second)return common_failure("DuplicateKnownPersonalDialogueSession",s.id);}
 return common_success();
}
}
